def write_strings_xml(path, lang_dict, is_default=False):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write('<?xml version="1.0" encoding="utf-8"?>\n<resources>\n')
        for key, value in strings.items():
            translated = lang_dict.get(key, value) if not is_default else value
            escaped = translated.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("'", "\\'")
            f.write(f'    <string name="{key}">{escaped}</string>\n')
        f.write("</resources>\n")


# Default English
write_strings_xml(os.path.join(BASE_DIR, "values", "strings.xml"), {}, is_default=True)

# Translations
for lang_code, trans in translations.items():
    if lang_code == "zh":
        folder = "values-zh"
    elif lang_code == "ko":
        folder = "values-ko"
    elif lang_code == "ar":
        folder = "values-ar"
    else:
        folder = f"values-{lang_code}"
    write_strings_xml(os.path.join(BASE_DIR, folder, "strings.xml"), trans)

print("Done! Generated strings.xml files for 10 languages.")
